import importlib.util
from zipfile import ZipFile
with ZipFile('panel_train.npz') as panel:
    print('Archive members:', panel.namelist())
libs = {name: importlib.util.find_spec(name) is not None for name in ('numpy', 'scipy', 'sklearn')}
print('Available libraries:', libs)
if libs['numpy']:
    import numpy as np
    with np.load('panel_train.npz', allow_pickle=False) as panel:
        for name in panel.files:
            a = panel[name]
            print(name, a.shape, a.dtype)
            if a.ndim == 2 and np.issubdtype(a.dtype, np.number):
                print('  nonfinite fraction:', (~np.isfinite(a)).mean())
            elif a.ndim == 1:
                v, n = np.unique(a, return_counts=True)
                if len(v) <= 20:
                    print('  counts:', list(zip(v.tolist(), n.tolist())))
